        public void post(Queue q,Object key,Object token,long delay,Runnable action){jobs.add(new Job(q,key,token,up+Math.max(0,delay),action));}
        public void removeCallbacks(Queue q,Object key){jobs.removeIf(j->j.queue==q&&j.key==key);}
        public void removeToken(Queue q,Object token){jobs.removeIf(j->j.queue==q&&(token==null||j.token==token));}
